#include "BombYoumu.hpp"
#include <cmath>
namespace th17 {
bool BombYoumu::start(){position=context.motion.position;if(!sound(49,true))return false;invalidate_spell();context.invulnerability.set(120);context.session.roaring_breaks=wrapping_add(context.session.roaring_breaks,1);if(!context.world.screen_effect({8,1,6,context.session.animal==1?320:230,30}))return fail("Bomb screen effect unavailable");aura_handle=animation(30,position);auto* aura=context.animations.registry.find(aura_handle);if(!aura)return false;aura->visual.color=(aura->visual.color&0xffffff)|0xe0000000u;aura->interpolators.alpha.end[0]=224;interval=context.session.animal==1?15:25;spawn_age.set(0);emitted=0;age.set(0);return true;}
bool BombYoumu::frame(bool& finished){
    context.invulnerability.set(40);const i32 duration=context.session.animal==1?350:260;if(age.current>duration){finished=true;return interrupt(aura_handle);}
    if(age.current!=age.previous&&spawn_age.current<1){if(emitted>=i32(handles.size()))return fail("Youmu bomb animation capacity exceeded");static constexpr float base[]={224,192,320,224,64,80,384,320,96,128,224};const float y=float(float(context.random.signed_unit()*48.f)+base[u32(emitted)%11]);heights[emitted]=y;sides[emitted]=emitted&1?192.f:-192.f;handles[emitted]=animation(22+(emitted&1)+(context.session.animal==1?2:0),{0,y,0});if(!handles[emitted])return false;timers[emitted].set(0);emitted++;if(interval>(context.session.animal==1?6:8))interval-=2;spawn_age.set(interval);if(!sound(44,true)||!sound(27,true))return false;}
    spawn_age.decrement(&rate);
    for(u32 i=0;i<handles.size();i++){auto* vm=context.animations.registry.find(handles[i]);if(!vm){handles[i]=0;continue;}const float bearing=float(vm->variables.rotation.z+1.57079637050628662109375f);const Vec3 offset{float(std::cos(double(bearing))*256.),float(std::sin(double(bearing))*256.),0};Vec3 p{0,heights[i],0};if(sides[i]<0)p={float(p.x-offset.x),float(p.y-offset.y),float(p.z-offset.z)};else p={float(offset.x+p.x),float(offset.y+p.y),float(offset.z+p.z)};const Vec2 size{96,float(timers[i].fractional*128)};if(!rectangle(p,vm->variables.rotation.z,size,0,30))return false;if(!context.world.cancel_bullets_rectangle(p,size,vm->variables.rotation.z,0)||!context.world.cancel_lasers_rectangle(p,size,vm->variables.rotation.z,0,true))return fail("Youmu bomb rectangle cancellation failed");timers[i].tick(&rate);}return true;
}
}
